function field(data, names) {
  if (!data || typeof data !== 'object') return '';
  const wanted = names.map((name) => name.toLowerCase());

  for (const [key, value] of Object.entries(data)) {
    if (wanted.includes(String(key).toLowerCase()) && value != null && value !== '') {
      return Array.isArray(value) ? value.join(', ') : String(value);
    }
  }

  if (Array.isArray(data.fields)) {
    for (const entry of data.fields) {
      const label = String(entry.name || entry.label || entry.id || '').toLowerCase();
      if (wanted.some((name) => label.includes(name) || name.includes(label))) {
        return String(entry.value ?? '');
      }
    }
  }

  if (Array.isArray(data.field_data)) {
    for (const entry of data.field_data) {
      if (wanted.includes(String(entry.name).toLowerCase())) {
        return String(entry.values?.[0] ?? '');
      }
    }
  }

  return '';
}

function buildExternalId(payload) {
  return payload.entry_id
    || payload.entryId
    || payload.submission_id
    || payload.submissionId
    || payload.id
    || payload.token
    || `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

return items.map((item) => {
  const payload = item.json.body ?? item.json;
  const firstName = field(payload, ['first_name', 'firstname', 'fname']);
  const lastName = field(payload, ['last_name', 'lastname', 'lname']);
  const fullName = field(payload, ['full_name', 'name', 'your-name', 'your name', 'customer name'])
    || [firstName, lastName].filter(Boolean).join(' ');

  return {
    json: {
      source: 'wordpress',
      external_id: String(buildExternalId(payload)),
      full_name: fullName,
      email: field(payload, ['email', 'your-email', 'e-mail']),
      phone: field(payload, ['phone', 'phone_number', 'mobile', 'tel', 'your-phone']),
      service_requested: field(payload, ['service', 'service_requested', 'service type', 'subject', 'requested service', 'job description']),
      message: field(payload, ['message', 'comments', 'details', 'your-message', 'additional information', 'enquiry', 'project summary']),
      raw_payload: payload,
      received_at: payload.date || payload.submitted_at || payload.created_at || new Date().toISOString()
    }
  };
});
